WITH upsert AS (
    UPDATE fnd07_issuing_entity
       SET fnd07_issuing_entity_cd           = #{row.issuingEntityCode}
         , fnd07_issuing_entity_nm           = #{row.issuingEntityName}
         , fnd07_issuing_entity_face_value   = #{row.issuingEntityFaceValue}
         , fnd07_issuing_entity_settle_month = #{row.issuingEntitySettleMonth}
         , fnd07_issuing_entity_nation_cd    = #{row.issuingEntityNationCode}
         , fnd07_issuing_entity_use_yn       = #{row.issuingEntityUseYn}
         , fnd07_issuing_entity_note         = #{row.issuingEntityNote}
         , fnd07_issuing_entity_attach_cd    = #{row.issuingEntityAttachCode}
         , fnd07_company_id                  = #{row.companyId}
     WHERE fnd07_issuing_entity_id = #{row.issuingEntityId}
    RETURNING *
)
INSERT INTO fnd07_issuing_entity
( fnd07_issuing_entity_id
, fnd07_issuing_entity_cd
, fnd07_issuing_entity_nm
, fnd07_issuing_entity_attach_cd
, fnd07_issuing_entity_face_value
, fnd07_issuing_entity_settle_month
, fnd07_issuing_entity_nation_cd
, fnd07_issuing_entity_use_yn
, fnd07_issuing_entity_note
, fnd07_company_id )
SELECT #{row.issuingEntityId}
     , #{row.issuingEntityCode}
     , #{row.issuingEntityName}
     , #{row.issuingEntityAttachCode}
     , #{row.issuingEntityFaceValue}
     , #{row.issuingEntitySettleMonth}
     , #{row.issuingEntityNationCode}
     , #{row.issuingEntityUseYn}
     , #{row.issuingEntityNote}
     , #{row.companyId}
 WHERE NOT EXISTS ( SELECT * FROM upsert )

